/**
 * @file scripts/generate-profile-validator.ts
 * @description Compile the profile JSON Schema into the standalone validator
 * the runtime imports (`src/profile/schema/profile-validator.generated.ts`),
 * so no process loads Ajv or compiles the schema to validate a profile.
 *
 *   bun scripts/generate-profile-validator.ts     rewrite the generated file
 *
 * `test/profile-validator-generated.test.ts` fails when the committed file no
 * longer matches the schema.
 */

import Ajv2020 from "ajv/dist/2020.js";
import standaloneCode from "ajv/dist/standalone/index.js";
import path from "node:path";
import schema from "../src/profile/schema/profile.v1.schema.json" with { type: "json" };

/** Where the generated validator lives. */
export const GENERATED_VALIDATOR = path.join(import.meta.dir, "../src/profile/schema/profile-validator.generated.ts");

/**
 * The generated module's source. `strict` surfaces any schema authoring
 * mistake, the meta-schema check runs here rather than at runtime, and
 * `allErrors` collects every violation for a complete message.
 */
export function profileValidatorSource(): string {
  const ajv = new Ajv2020({ allErrors: true, strict: true, code: { source: true, esm: true } });
  // Ajv's ESM output still `require`s its runtime helpers; make them imports.
  // A CommonJS default import is `module.exports` under Node and its
  // `default` export under Bun and bundlers, so take whichever holds it.
  const imports: string[] = [];
  const code = standaloneCode(ajv, ajv.compile(schema)).replace(
    /const (\w+) = require\("([^"]+)"\)\.default;/gu,
    (_match, name: string, from: string) => {
      imports.push(`import ${name}Module from "${from}.js";`);
      return `const ${name} = ${name}Module.default ?? ${name}Module;`;
    },
  );
  return [
    "/**",
    " * @file src/profile/schema/profile-validator.generated.ts",
    " * @description GENERATED by `bun scripts/generate-profile-validator.ts` from",
    " * `profile.v1.schema.json`. Do not edit.",
    " */",
    "// @ts-nocheck",
    ...imports,
    code,
    "",
  ].join("\n");
}

if (import.meta.main) await Bun.write(GENERATED_VALIDATOR, profileValidatorSource());
